const { useState } = React;

const URL = '/api/save';

function CourseForm() {
  const [title, setTitle] = useState('');
  const [sending, setSending] = useState(false);
  const [result, setResult] = useState('아직 보내지 않았습니다');

  const submit = (e) => {
    e.preventDefault();
    if (sending) return;

    setSending(true);
    setResult('보내는 중…');

    fetch(URL)
      .then((res) => {
        if (!res.ok) throw new Error('저장하지 못했습니다 (' + res.status + ')');
        setResult('저장했습니다: ' + title);
      })
      .catch((err) => setResult('실패: ' + err.message))
      .finally(() => setSending(false));
  };

  return (
    <form onSubmit={submit}>
      <label className="field" htmlFor="title">제목</label>
      <input className="field__input" id="title" name="title" value={title} onChange={(e) => setTitle(e.target.value)} />

      <button className="go" type="submit" disabled={sending}>{sending ? '보내는 중…' : '저장'}</button>

      <p className="result">{result}</p>
    </form>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<CourseForm />);

